using System.Collections;using System.IO;using NUnit.Framework;using UnityEngine;using UnityEngine.TestTools;
namespace OneMoreTime.Tests {
public class MotorTests {
 GameObject root;PlayerMotor2D motor;PlayerTuning tuning;
 [SetUp]public void Setup(){root=new GameObject("Fixture");tuning=ScriptableObject.CreateInstance<PlayerTuning>();var p=new GameObject("Player");p.transform.SetParent(root.transform);motor=p.AddComponent<PlayerMotor2D>();motor.tuning=tuning;motor.worldMask=1<<31;Box(new Rect(-10,-2,50,2));motor.Init();motor.ResetAt(Vector2.zero);Physics2D.SyncTransforms();Tick(default,2);}
 void Box(Rect r){var g=new GameObject("World");g.transform.SetParent(root.transform);g.layer=31;g.transform.position=r.center;g.AddComponent<BoxCollider2D>().size=r.size;Physics2D.SyncTransforms();}
 void Tick(InputFrame f,int n=1){for(int i=0;i<n;i++){motor.Step(f,.02f);f.jump=false;Physics2D.SyncTransforms();}}
 [TearDown]public void Teardown(){Object.DestroyImmediate(root);Object.DestroyImmediate(tuning);}
 [Test] public void LongShortAndNoDoubleJump(){Tick(new InputFrame{jump=true,held=true});float high=0;for(int i=0;i<100;i++){Tick(new InputFrame{held=true,jump=i%5==0&&i<35});high=Mathf.Max(high,motor.Position.y);}Assert.That(high,Is.InRange(2.8f,3.1f));motor.ResetAt(Vector2.zero);Tick(default,2);Tick(new InputFrame{jump=true,held=true});Tick(default,5);Assert.Less(motor.Position.y,high/2);}
 [Test]public void VisualPosesFollowMotionAndSnapshotFreezesExactFrame(){Tick(default,20);Assert.AreEqual(0,motor.VisualState);Tick(new InputFrame{move=1},10);Assert.AreEqual(1,motor.VisualState);Tick(default,10);Tick(new InputFrame{jump=true,held=true},1);Assert.AreEqual(2,motor.VisualState);var saved=new MemorySnapshot(new RecordedFrame(.02f,motor),1);int frame=saved.FreezePose.frame;Tick(new InputFrame{held=true},27);Assert.AreEqual(3,motor.VisualState);for(int i=0;i<50&&!motor.Grounded;i++)Tick(new InputFrame{held=true});Assert.AreEqual(4,motor.VisualState);Tick(default,20);Assert.AreEqual(0,motor.VisualState);Assert.AreEqual(2,saved.FreezePose.state);Assert.AreEqual(frame,saved.FreezePose.frame);}
 [Test] public void MeasureJump(){Tick(new InputFrame{move=1,held=true},10);float start=motor.Position.x,max=0;Tick(new InputFrame{move=1,jump=true,held=true});for(int i=0;i<100;i++){max=Mathf.Max(max,motor.Position.y);if(motor.Grounded)break;Tick(new InputFrame{move=1,held=true});}Directory.CreateDirectory("Artifacts/Logs");File.WriteAllText("Artifacts/Logs/jump-measurement.txt",$"Unity={Application.unityVersion}; dt=.02; H={max:F5}; D={motor.Position.x-start:F5}; B={tuning.backHeight}; feet={motor.Position}");Assert.That(max,Is.InRange(2.8f,3.1f));}
 [Test] public void WallsCeilingAndDeceleration(){Box(new Rect(3,0,1,7));Tick(new InputFrame{move=1},100);Assert.LessOrEqual(motor.Position.x,2.651f);Tick(default,10);Assert.AreEqual(0,motor.Velocity.x);motor.ResetAt(Vector2.zero);Box(new Rect(-1,2,3,.5f));Tick(default,2);Tick(new InputFrame{jump=true,held=true});Tick(new InputFrame{held=true},20);Assert.Less(motor.Position.y,1.01f);}
 [TestCase(1f,0f)][TestCase(0f,1f)][TestCase(0f,-1f)][TestCase(1f,1f)]public void EchoCarry(float x,float y){motor.ResetAt(new Vector2(0,5));Vector2 echo=new Vector2(0,3);for(int i=0;i<40;i++)motor.Step(default,.02f,true,echo,echo);Assert.IsTrue(motor.OnEcho);var relative=motor.Position-echo;for(int i=0;i<50;i++){var next=echo+new Vector2(x,y)*.02f;motor.Step(default,.02f,true,echo,next);echo=next;}Assert.That(Vector2.Distance(relative,motor.Position-echo),Is.LessThan(.005f));motor.Step(new InputFrame{jump=true,held=true},.02f,true,echo,echo+Vector2.up*.1f);Assert.That(motor.Velocity.y,Is.EqualTo(13.36f).Within(.001));Assert.IsFalse(motor.OnEcho);}
 [Test]public void EchoDisappearsAndDoesNotPullFromBelow(){motor.ResetAt(new Vector2(0,1));Vector2 e=new Vector2(0,3);motor.Step(default,.02f,true,e,e);Assert.IsFalse(motor.OnEcho);motor.ResetAt(new Vector2(0,5));for(int i=0;i<40;i++)motor.Step(default,.02f,true,e,e);Assert.IsTrue(motor.OnEcho);motor.Step(default,.02f,false);Assert.IsFalse(motor.OnEcho);Assert.Less(motor.Velocity.y,0);}
 [Test]public void CoyoteAndBufferWindows(){foreach(var c in root.GetComponentsInChildren<BoxCollider2D>())if(c.gameObject.layer==31)c.enabled=false;Box(new Rect(-10,-2,10,2));motor.ResetAt(new Vector2(-.5f,0));Tick(default,2);for(int i=0;i<30&&motor.Grounded;i++)Tick(new InputFrame{move=1});Tick(new InputFrame{move=1},2);Tick(new InputFrame{jump=true,held=true});Assert.Greater(motor.Velocity.y,13);motor.ResetAt(new Vector2(-.5f,0));Tick(default,2);for(int i=0;i<30&&motor.Grounded;i++)Tick(new InputFrame{move=1});Tick(new InputFrame{move=1},10);Tick(new InputFrame{jump=true,held=true});Assert.Less(motor.Velocity.y,0);motor.ResetAt(new Vector2(-3,.1f));Tick(new InputFrame{jump=true,held=true});Tick(new InputFrame{held=true},5);Assert.Greater(motor.Velocity.y,0);motor.ResetAt(new Vector2(-3,5));Tick(new InputFrame{jump=true,held=true});Tick(new InputFrame{held=true},70);Assert.IsTrue(motor.Grounded);Assert.AreEqual(0,motor.Velocity.y);}
 [Test]public void EchoCeilingAndWalkOff(){Vector2 e=new Vector2(0,3);motor.ResetAt(new Vector2(0,5));for(int i=0;i<40;i++)motor.Step(default,.02f,true,e,e);Assert.IsTrue(motor.OnEcho);Box(new Rect(-2,5.5f,4,1));for(int i=0;i<100;i++){var next=e+Vector2.up*.03f;motor.Step(default,.02f,true,e,next);e=next;Assert.LessOrEqual(motor.Position.y,4.51f);}motor.ResetAt(new Vector2(0,5));Assert.IsFalse(motor.OnEcho);e=new Vector2(0,2);for(int i=0;i<50;i++)motor.Step(default,.02f,true,e,e);Assert.IsTrue(motor.OnEcho);for(int i=0;i<30;i++)motor.Step(new InputFrame{move=1},.02f,true,e,e);Assert.IsFalse(motor.OnEcho);Assert.Less(motor.Position.y,2.9f);}
 [Test]public void EchoCannotCarryThroughWorld(){Vector2 e=new Vector2(0,3);motor.ResetAt(new Vector2(0,5));for(int i=0;i<40;i++)motor.Step(default,.02f,true,e,e);Box(new Rect(1,2,1,5));for(int i=0;i<70;i++){var next=e+Vector2.right*.04f;motor.Step(default,.02f,true,e,next);e=next;}Assert.LessOrEqual(motor.Position.x,.651f);Assert.IsFalse(motor.OnEcho);}
 [TestCase(30)][TestCase(60)][TestCase(120)]public void RenderCadenceDoesNotAlterSimulation(int fps){float accumulator=0;int steps=0;for(int render=0;render<fps*2;render++){accumulator+=1f/fps;while(accumulator>=.02f-.000001f){motor.Step(new InputFrame{move=1,held=true,jump=steps==10},.02f);accumulator-=.02f;steps++;}}Assert.AreEqual(100,steps);Assert.That(motor.Position.x,Is.EqualTo(11.76f).Within(.015));}
 [UnityTest]public IEnumerator ActualRenderRates(){int oldRate=Application.targetFrameRate,oldSync=QualitySettings.vSyncCount;var report=new System.Text.StringBuilder();try{QualitySettings.vSyncCount=0;foreach(int fps in new[]{30,60,120}){Application.targetFrameRate=fps;yield return new WaitForSecondsRealtime(.3f);motor.ResetAt(Vector2.zero);Tick(default,2);var driver=root.AddComponent<MotorRateDriver>();driver.motor=motor;float start=Time.realtimeSinceStartup;int rendered=0;while(driver.steps<100){rendered++;yield return null;}float duration=Time.realtimeSinceStartup-start;report.AppendLine($"target={fps}; observedRenderFPS={rendered/duration:F2}; fixedSteps={driver.steps}; x={motor.Position.x:F5}; duration={duration:F3}");Assert.That(motor.Position.x,Is.EqualTo(11.76f).Within(.015));Object.DestroyImmediate(driver);}}finally{Application.targetFrameRate=oldRate;QualitySettings.vSyncCount=oldSync;File.WriteAllText("Artifacts/Logs/render-rates.txt",report.ToString());}}
 [UnityTest]public IEnumerator RealFixedUpdates(){var start=motor.Position;for(int i=0;i<20;i++){motor.Step(new InputFrame{move=1},.02f);yield return new WaitForFixedUpdate();}Assert.Greater(motor.Position.x,start.x+1);Assert.That(motor.Position.y,Is.EqualTo(0).Within(.01));}
}
public sealed class MotorRateDriver:MonoBehaviour {public PlayerMotor2D motor;public int steps;void FixedUpdate(){if(steps>=100)return;motor.Step(new InputFrame{move=1,held=true,jump=steps==10},.02f);steps++;}}
}
